#include "modules/pde_stiff_api.h"
#include "runtime/thread_budget.hpp"
#include <algorithm>
#include <chrono>
#include <cmath>
#include <complex>
#include <cstring>
#include <iostream>
#include <numbers>
#include <vector>

namespace {
int checks=0,failures=0;void expect(bool yes,const char* message){++checks;if(!yes){++failures;std::cerr<<"FAIL: "<<message<<'\n';}}
struct Host {penta::runtime::ParallelSettings settings;penta::runtime::ParallelStatistics statistics;uint64_t work=0;
    static int cancelled(void*){return 0;}static int charge(void* raw,uint64_t count,char*,uint64_t){static_cast<Host*>(raw)->work+=count;return 0;}
    static int parallel(void* raw,uint64_t count,uint64_t cost,penta_numeric_range_task_v1 task,void* data,char* error,uint64_t capacity){auto& self=*static_cast<Host*>(raw);penta::runtime::ParallelStatistics statistics;std::string text;const auto status=penta::runtime::ThreadBudget::instance().run(count,cost,task,data,self.settings,{},statistics,text);self.statistics.parallelCalls+=statistics.parallelCalls;self.statistics.threadsUsed=std::max(self.statistics.threadsUsed,statistics.threadsUsed);if(error&&capacity){const auto size=std::min<uint64_t>(capacity-1,text.size());std::memcpy(error,text.data(),size);error[size]=0;}return status;}
};
struct Reaction {unsigned kind=0;double rate=0;
    static int value(void* raw,double time,const double*,uint32_t,const double* u,uint32_t c,double* out,double* jac,char*,uint64_t){const auto& self=*static_cast<Reaction*>(raw);if(jac)std::fill_n(jac,c*c,0);for(unsigned k=0;k<c;++k){out[k]=self.kind==1?-self.rate*u[k]*u[k]*u[k]:self.kind==2?1:self.kind==3?-1:self.kind==4?-self.rate*(u[k]-std::cos(time))-std::sin(time):0;if(jac)jac[k*c+k]=self.kind==1?-3*self.rate*u[k]*u[k]:self.kind==4?-self.rate:0;}return 0;}
};
struct Boundary {unsigned kind=0;double diffusion=.2,velocity=0,alpha=0;
    static int value(void* raw,double time,uint64_t,const double* point,const double* normal,uint32_t,double* out,double* alpha,char*,uint64_t){const auto& self=*static_cast<Boundary*>(raw);*alpha=self.alpha;if(self.kind==1)out[0]=point[0]+time;else if(self.kind==2)out[0]=normal[0]*self.diffusion+self.alpha*(point[0]+time);else if(self.kind==3)out[0]=normal[0]*(1+point[0]+time);else if(self.kind==4)out[0]=-normal[0]*self.velocity;return 0;}
};
int coefficient(void*,double time,const double* point,uint32_t,double* diffusion,double* velocity,char*,uint64_t){diffusion[0]=1+point[0]+time;velocity[0]=0;return 0;}
penta_pde_stiff_request_v1 request(std::size_t nodes,unsigned components=1){penta_pde_stiff_request_v1 q{};q.struct_size=sizeof(q);q.abi_version=PENTA_PDE_STIFF_ABI_V1;q.method=PENTA_STIFF_FD1;q.dimension=1;q.components=components;q.nodes=q.nx=nodes;q.diffusion=.1;q.t1=.02;q.time_step=.01;q.sample_step=.01;q.minimum_step=1e-10;q.maximum_step=.1;q.rtol=1e-5;q.atol=1e-9;q.newton_tolerance=.001;q.linear_tolerance=1e-11;q.max_seconds=60;q.max_steps=100000;q.max_newton=20;q.max_linear=300;q.gmres_restart=30;q.max_work=1000000000;q.max_bytes=256*1024*1024;q.reaction=Reaction::value;return q;}
struct Result {int status=0;std::string error;std::vector<double> times,values,means,rms;penta_pde_stiff_result_v1 report{};Host host;};
Result run(penta_pde_stiff_request_v1 q,unsigned threads=1){Result result;const auto samples=static_cast<std::size_t>(std::ceil((q.t1-q.t0)/q.sample_step))+2;result.times.resize(samples);result.values.resize(samples*q.nodes*q.components);result.means.resize(samples*q.components);result.rms.resize(samples);auto& out=result.report;out.struct_size=sizeof(out);out.sample_capacity=samples;out.value_capacity=result.values.size();out.times=result.times.data();out.values=result.values.data();out.means=result.means.data();out.spatial_rms=result.rms.data();result.host.settings.threads=threads;result.host.settings.serialThreshold=1;penta_pde_parallel_host_v1 host{};host.base={sizeof(host),PENTA_PDE_ABI_V1,&result.host,Host::cancelled,Host::charge};host.threads_requested=host.threads_granted=threads;host.parallel_for=Host::parallel;char error[2048]{};penta::runtime::ThreadBudget::instance().withReservation([&]{result.status=penta_pde_stiff_query_v1(PENTA_PDE_STIFF_ABI_V1)->solve(&host.base,&q,&out,error,sizeof(error));});result.error=error;if(!result.status){result.times.resize(out.samples);result.values.resize(out.samples*q.nodes*q.components);result.means.resize(out.samples*q.components);result.rms.resize(out.samples);}return result;}
void valid(const Result& result,const char* message){if(result.status)std::cerr<<result.error<<'\n';expect(result.status==0,message);}
}
int main(){
    try{
        constexpr std::size_t n=33;std::vector<double> x(n),initial(n);for(std::size_t k=0;k<n;++k){x[k]=double(k)/(n-1);initial[k]=std::cos(std::numbers::pi*x[k]);}Reaction zero;auto q=request(n);q.x=x.data();q.initial=initial.data();q.reaction_context=&zero;auto heat=run(q);valid(heat,"Fully implicit FD heat accepts analytic zero reaction Jacobians.");if(!heat.status){const auto eigenvalue=4*q.diffusion*std::pow(std::sin(std::numbers::pi/(2*(n-1))),2)/std::pow(x[1]-x[0],2),amplitude=1/std::pow(1+q.time_step*eigenvalue,2);double error=0;for(std::size_t k=0;k<n;++k)error=std::max(error,std::abs(heat.values[(heat.report.samples-1)*n+k]-amplitude*initial[k]));expect(error<1e-9,"Implicit FD heat matches its independent discrete eigenmode amplification.");expect(heat.report.jacobian_evaluations>0&&heat.report.maximum_nonzeros<6*n,"Local generated Jacobians assemble a sparse global Newton system.");}
        std::vector<double> parallelX(257),parallelInitial(257);for(std::size_t k=0;k<parallelX.size();++k){parallelX[k]=double(k)/(parallelX.size()-1);parallelInitial[k]=std::cos(std::numbers::pi*parallelX[k]);}auto parallelRequest=request(parallelX.size());parallelRequest.x=parallelX.data();parallelRequest.initial=parallelInitial.data();parallelRequest.reaction_context=&zero;const auto serialLarge=run(parallelRequest),parallel=run(parallelRequest,2);valid(parallel,"Implicit sparse solves execute under the shared CPU thread budget.");if(!parallel.status&&!serialLarge.status)expect(parallel.values==serialLarge.values&&parallel.host.statistics.parallelCalls>0&&parallel.host.statistics.threadsUsed<=2,"Parallel and serial fields agree exactly while assembly/matvec dispatch through the granted CPU budget.");
        q=request(n,2);std::vector<double> pair(n*2),block{.1,-.2,.2,.1};for(std::size_t k=0;k<n;++k)pair[2*k]=initial[k];q.x=x.data();q.initial=pair.data();q.diffusion_block=block.data();q.reaction_context=&zero;auto ordered=run(q);valid(ordered,"Nonsymmetric ordered diffusion blocks with positive symmetric part are supported.");if(!ordered.status){const auto lambda=4*std::pow(std::sin(std::numbers::pi/(2*(n-1))),2)/std::pow(x[1]-x[0],2);const auto amplitude=1./std::pow(1.+q.time_step*lambda*std::complex<double>(.1,.2),2);double error=0;for(std::size_t k=0;k<n;++k){error=std::max(error,std::abs(ordered.values[(ordered.report.samples-1)*n*2+2*k]-amplitude.real()*initial[k]));error=std::max(error,std::abs(ordered.values[(ordered.report.samples-1)*n*2+2*k+1]-amplitude.imag()*initial[k]));}expect(error<1e-8,"Ordered diffusion reproduces an independent complex-valued mode without discarding coupling.");}
        std::vector<double> constant(n,1);Reaction nonlinear{1,1000};q=request(n);q.x=x.data();q.initial=constant.data();q.diffusion=0;q.reaction_context=&nonlinear;q.adaptive=1;q.time_step=.02;q.rtol=2e-3;q.atol=1e-8;auto stiff=run(q);valid(stiff,"Adaptive fully implicit integration handles a stiff nonlinear cubic reaction.");if(!stiff.status){const double exact=1/std::sqrt(1+2000*q.t1);expect(std::abs(stiff.values.back()-exact)<.004,"Adaptive nonlinear result agrees with the independent closed-form solution.");expect(stiff.report.rejected_steps>0&&stiff.report.accepted_steps>1,"Adaptive error control rejects the oversized first step and refines it.");}
        Reaction source{2,0};Boundary boundary{1,.2,0,0};penta_stiff_boundary_edge_v1 ends[2]{{1,1,1,PENTA_STIFF_DIRICHLET,0,0,nullptr},{n,n,2,PENTA_STIFF_DIRICHLET,0,0,nullptr}};q=request(n);q.x=x.data();q.initial=x.data();q.diffusion=.2;q.reaction_context=&source;q.boundaries=ends;q.boundary_count=2;q.boundary_context=&boundary;q.boundary=Boundary::value;auto dynamic=run(q);valid(dynamic,"Time-dependent Dirichlet values enter fully implicit boundary equations.");if(!dynamic.status){double error=0;for(std::size_t k=0;k<n;++k)error=std::max(error,std::abs(dynamic.values[(dynamic.report.samples-1)*n+k]-x[k]-q.t1));expect(error<1e-8,"A manufactured affine space-time solution is reproduced with dynamic Dirichlet boundaries.");}
        boundary.kind=2;ends[0].kind=ends[1].kind=PENTA_STIFF_FLUX;auto flux=run(q);valid(flux,"Inhomogeneous outward total-flux boundary conditions are supported.");if(!flux.status)expect(std::abs(flux.values.back()-1-q.t1)<1e-8,"Outward flux signs agree with an independent affine manufactured solution.");boundary.alpha=2;ends[0].kind=ends[1].kind=PENTA_STIFF_ROBIN;auto robin=run(q);valid(robin,"Robin boundaries combine nonzero flux and value contributions.");if(!robin.status)expect(std::abs(robin.values.back()-1-q.t1)<1e-8,"Robin alpha and data enter the same fully implicit time level.");
        Reaction minus{3,0};boundary={3,0,0,0};q.reaction_context=&minus;q.coefficient=coefficient;ends[0].kind=ends[1].kind=PENTA_STIFF_FLUX;auto varying=run(q);valid(varying,"Spatial and temporal native diffusion callbacks assemble changing operators.");if(!varying.status)expect(std::abs(varying.values.back()-1)<1e-8&&varying.report.operator_evaluations>0,"Variable diffusion and matching boundary flux retain the manufactured steady affine field.");
        q=request(n);q.x=x.data();q.initial=constant.data();q.reaction_context=&zero;double velocity=2;q.velocity=&velocity;q.boundaries=ends;q.boundary_count=2;boundary={4,0,2,0};q.boundary_context=&boundary;q.boundary=Boundary::value;auto advection=run(q);valid(advection,"Conservative upwind advection is supported with total-flux boundary data.");if(!advection.status)expect(std::abs(advection.values.back()-1)<1e-8,"Advection flux orientation preserves a compatible constant field.");
        std::vector<double> periodicX(32),periodicInitial(32);for(std::size_t k=0;k<32;++k){periodicX[k]=2*std::numbers::pi*k/32;periodicInitial[k]=std::cos(periodicX[k]);}penta_stiff_boundary_edge_v1 periodicEnds[2]{{1,1,1,PENTA_STIFF_PERIODIC,0,0,nullptr},{32,32,2,PENTA_STIFF_PERIODIC,0,0,nullptr}};q=request(32);q.x=periodicX.data();q.initial=periodicInitial.data();q.reaction_context=&zero;q.boundaries=periodicEnds;q.boundary_count=2;auto periodic=run(q);valid(periodic,"Fully implicit periodic FD closes the wraparound diffusion stencil.");if(!periodic.status){const auto lambda=4*q.diffusion*std::pow(std::sin(std::numbers::pi/32),2)/std::pow(periodicX[1]-periodicX[0],2),amplitude=1/std::pow(1+q.time_step*lambda,2);expect(std::abs(periodic.values.back()-amplitude*periodicInitial.back())<1e-9,"Periodic wraparound uses the neighboring-cell spacing and correct mass weights.");}
        std::vector<double> points{0,0,1,0,1,1,0,1},flat(4,3);std::vector<uint64_t> faces{1,2,3,1,3,4};q=request(4);q.method=PENTA_STIFF_TRIANGLE_P1;q.dimension=2;q.points=points.data();q.faces=faces.data();q.triangles=2;q.initial=flat.data();q.reaction_context=&zero;auto surface=run(q);valid(surface,"Unstructured lumped P1 surface heat uses the implicit sparse solver.");if(!surface.status)expect(std::all_of(surface.values.begin(),surface.values.end(),[](double value){return std::abs(value-3)<1e-12;}),"P1 natural-boundary heat preserves an independent constant state exactly.");
        struct Samples {unsigned calls=0;std::vector<double> times;static int emit(void* raw,double time,const double* values,uint64_t nodes,uint32_t c,char*,uint64_t){auto& self=*static_cast<Samples*>(raw);++self.calls;self.times.push_back(time);return nodes==n&&c==1&&std::isfinite(values[0])&&time>=.01?1:0;}} samples;
        q=request(n);q.x=x.data();q.initial=initial.data();q.reaction_context=&zero;q.sample=Samples::emit;q.sample_context=&samples;const auto stopped=run(q);valid(stopped,"Driver sample observer can stop with a retained partial field.");expect(samples.calls==2&&samples.times==std::vector<double>({0,.01})&&stopped.report.samples==2&&std::string(stopped.report.status)=="user_stopped","Sample observer receives complete ordered coefficients at retained times and an honest stop status.");
        q=request(n);q.x=x.data();q.initial=initial.data();q.reaction_context=&zero;q.diffusion=-1;expect(run(q).status!=0,"Negative scalar diffusivity is rejected before integration.");q.diffusion=.1;q.max_bytes=1048576;q.gmres_restart=64;q.nodes=q.nx=4096;expect(run(q).status!=0,"The combined Krylov/block/output storage bound is checked before reading large initial arrays.");
    }catch(const std::exception& error){++failures;std::cerr<<"Unexpected exception: "<<error.what()<<'\n';}
    std::cout<<checks<<" stiff PDE kernel checks, "<<failures<<" failures\n";return failures?1:0;
}
